57	export function MemoFilterProvider({ children }: { children: ReactNode }) {
58	  const [searchParams, setSearchParams] = useSearchParams();
59	  const lastSyncedUrlRef = useRef("");
60	  const lastSyncedStoreRef = useRef("");
61	
62	  // Initialize from URL
63	  const [filters, setFiltersState] = useState<MemoFilter[]>(() => {
64	    return parseFilterQuery(searchParams.get("filter"));
65	  });
66	  const [shortcut, setShortcutState] = useState<string | undefined>(undefined);
67	
68	  // Sync URL to state when URL changes externally
69	  useEffect(() => {
70	    const filterParam = searchParams.get("filter") || "";
71	    if (filterParam !== lastSyncedUrlRef.current) {
72	      lastSyncedUrlRef.current = filterParam;
73	      const newFilters = parseFilterQuery(filterParam);
74	      setFiltersState(newFilters);
75	      lastSyncedStoreRef.current = stringifyFilters(newFilters);
76	    }
77	  }, [searchParams]);
78	
79	  // Sync state to URL when state changes
80	  useEffect(() => {
81	    const storeString = stringifyFilters(filters);
82	    if (storeString !== lastSyncedStoreRef.current && storeString !== lastSyncedUrlRef.current) {
83	      lastSyncedStoreRef.current = storeString;
84	      const newParams = new URLSearchParams(searchParams);
85	      if (filters.length > 0) {
86	        newParams.set("filter", storeString);
87	      } else {
88	        newParams.delete("filter");
89	      }
90	      setSearchParams(newParams, { replace: true });
91	      lastSyncedUrlRef.current = filters.length > 0 ? storeString : "";
92	    }
93	  }, [filters, searchParams, setSearchParams]);
94	
95	  const getFiltersByFactor = useCallback((factor: FilterFactor) => filters.filter((f) => f.factor === factor), [filters]);
96	
97	  const setFilters = useCallback((newFilters: MemoFilter[]) => {
98	    setFiltersState(newFilters);
99	  }, []);
100	
101	  const addFilter = useCallback((filter: MemoFilter) => {
102	    setFiltersState((prev) => uniqBy([...prev, filter], getMemoFilterKey));
103	  }, []);
104	
105	  const removeFilter = useCallback((predicate: (f: MemoFilter) => boolean) => {
106	    setFiltersState((prev) => prev.filter((f) => !predicate(f)));
107	  }, []);
108	
109	  const removeFiltersByFactor = useCallback((factor: FilterFactor) => {
110	    setFiltersState((prev) => prev.filter((f) => f.factor !== factor));
111	  }, []);
112	
113	  const clearAllFilters = useCallback(() => {
114	    setFiltersState([]);
115	    setShortcutState(undefined);
116	  }, []);
117	
118	  const setShortcut = useCallback((newShortcut?: string) => {
119	    setShortcutState(newShortcut);
120	    // Clear content search filter when selecting a shortcut (issue #5462)
121	    if (newShortcut !== undefined) {
