132	      value={{
133	        filters,
134	        shortcut,
135	        hasActiveFilters,
136	        getFiltersByFactor,
137	        setFilters,
138	        addFilter,
139	        removeFilter,
140	        removeFiltersByFactor,
141	        clearAllFilters,
142	        setShortcut,
